<?php
require __DIR__.'/../app/bootstrap.php'; require_role(['admin','collector','expert']);
$assetNo=preg_replace('/[^0-9]/','',(string)($_GET['asset_no']??$_POST['asset_no']??''));if(!preg_match('/^\d{7}$/',$assetNo))redirect('assets.php');$st=db()->prepare('SELECT * FROM assets WHERE asset_no=?');$st->execute([$assetNo]);$asset=$st->fetch();if(!$asset){flash('danger','تجهیز موردنظر پیدا نشد.');redirect('assets.php');}if(!can_manage_asset_type($asset['asset_type'],'edit')){http_response_code(403);exit('برای ویرایش این پایگاه دسترسی ندارید.');}
$technical=json_decode((string)$asset['technical'],true)?:[];$people=db()->query('SELECT id,full_name,personnel_code FROM personnel ORDER BY full_name LIMIT 5000')->fetchAll();$q=db()->prepare('SELECT * FROM asset_disks WHERE asset_no=? ORDER BY disk_index');$q->execute([$assetNo]);$disks=$q->fetchAll();$q=db()->prepare('SELECT * FROM asset_ram_slots WHERE asset_no=? ORDER BY slot_no');$q->execute([$assetNo]);$rams=$q->fetchAll();$error=null;$arrayFields=CsvImporter::arrayFields();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$type=(string)($_POST['asset_type']??'');if(!in_array($type,['computer','printer','display','scanner'],true)||!can_manage_asset_type($type,'edit'))throw new RuntimeException('برای این نوع تجهیز اجازه ویرایش ندارید.');
 $newTech=[];foreach(($_POST['technical']??[]) as $k=>$v){$s=trim((string)$v);if(in_array($k,$arrayFields,true)){if($s===''){$newTech[$k]=[];continue;}$d=json_decode($s,true);if(json_last_error()!==JSON_ERROR_NONE||!is_array($d))throw new RuntimeException('فیلد آرایه‌ای «'.$k.'» باید JSON معتبر باشد.');$newTech[$k]=array_values($d);}else{$newTech[$k]=$s;}}
 if(in_array($type,['printer','scanner'],true)){unset($newTech['MACAddresses']);}
 $db=db();$db->beginTransaction();$q=$db->prepare('UPDATE assets SET asset_type=?,device_subtype=?,hostname=?,personnel_id=?,location=?,department=?,manufacturer=?,model=?,serial_no=?,technical=?,status=?,updated_by=? WHERE asset_no=?');$q->execute([$type,trim((string)($_POST['device_subtype']??'')),trim((string)($_POST['hostname']??'')),($_POST['personnel_id']??'')!==''?(int)$_POST['personnel_id']:null,trim((string)($_POST['location']??'')),trim((string)($_POST['department']??'')),trim((string)($_POST['manufacturer']??'')),trim((string)($_POST['model']??'')),trim((string)($_POST['serial_no']??'')),json_encode($newTech,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE),$_POST['status']??'active',user()['id'],$assetNo]);
 $db->prepare('DELETE FROM asset_disks WHERE asset_no=?')->execute([$assetNo]);if($type==='computer')foreach(($_POST['disks']??[]) as $i=>$d){if(trim((string)($d['model']??''))===''&&trim((string)($d['serial_no']??''))===''&&trim((string)($d['size_gb']??''))==='')continue;$q=$db->prepare('INSERT INTO asset_disks(asset_no,disk_index,model,size_gb,serial_no,interface_name,media) VALUES(?,?,?,?,?,?,?)');$q->execute([$assetNo,$i+1,trim((string)($d['model']??'')),($d['size_gb']??'')!==''?(float)$d['size_gb']:null,trim((string)($d['serial_no']??'')),trim((string)($d['interface_name']??'')),trim((string)($d['media']??''))]);}
 $db->prepare('DELETE FROM asset_ram_slots WHERE asset_no=?')->execute([$assetNo]);if($type==='computer')foreach(($_POST['rams']??[]) as $r){if(trim((string)($r['slot_no']??''))==='')continue;$state=$r['state']??'unknown';if(!in_array($state,['empty','occupied','unknown'],true))$state='unknown';$q=$db->prepare('INSERT INTO asset_ram_slots(asset_no,slot_no,state,capacity_gb,ram_type,speed_mhz,manufacturer,part_number,serial_no) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$assetNo,trim((string)$r['slot_no']),$state,($r['capacity_gb']??'')!==''?(float)$r['capacity_gb']:null,trim((string)($r['ram_type']??'')),($r['speed_mhz']??'')!==''?(int)$r['speed_mhz']:null,trim((string)($r['manufacturer']??'')),trim((string)($r['part_number']??'')),trim((string)($r['serial_no']??''))]);}
 $db->commit();audit('asset_updated','asset',$assetNo,['type'=>$type]);flash('success','اطلاعات تجهیز به‌روزرسانی شد.');redirect('asset_view.php?asset_no='.urlencode($assetNo));}catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();$error=$e->getMessage();}}
$technicalKeys=['computer'=>['SystemType'=>'نوع سیستم','OSName'=>'سیستم‌عامل','OSVersion'=>'نسخه سیستم‌عامل','OSBuild'=>'Build سیستم‌عامل','OSArchitecture'=>'معماری','CPUName'=>'CPU','CPUManufacturer'=>'سازنده CPU','CPUCores'=>'هسته CPU','CPULogicalProcessors'=>'پردازنده منطقی','CPUMaxClockMHz'=>'حداکثر فرکانس CPU (MHz)','GPUDetails'=>'GPU','RAMTotalGB'=>'RAM کل (GB)','RAMSlotCount'=>'تعداد اسلات RAM','MotherboardManufacturer'=>'سازنده مادربرد','MotherboardProduct'=>'مدل مادربرد','MotherboardVersion'=>'نسخه مادربرد','MotherboardSerial'=>'سریال مادربرد','MotherboardChipset'=>'چیپست مادربرد','MotherboardMaxRAMGB'=>'حداکثر RAM مادربرد (GB)','BIOSManufacturer'=>'سازنده BIOS','BIOSVersion'=>'نسخه BIOS','BIOSSerial'=>'سریال BIOS','BIOSReleaseDate'=>'تاریخ BIOS','IPAddresses'=>'IP (JSON)','MACAddresses'=>'MAC (JSON)','SubnetMasks'=>'Subnet (JSON)','Gateways'=>'Gateway (JSON)','DNSServers'=>'DNS (JSON)','Domain'=>'دامنه/Workgroup','AntivirusDetails'=>'آنتی‌ویروس','NetworkDetails'=>'شبکه','MonitorDetails'=>'نمایشگر','SoundDetails'=>'صدا','PageFileDetails'=>'Page File','Building'=>'ساختمان','Floor'=>'طبقه','Room'=>'اتاق'], 'printer'=>['PrinterType'=>'نوع چاپگر','PrinterCapabilities'=>'قابلیت‌ها','ColorMode'=>'رنگی/سیاه‌وسفید','Connection'=>'نوع اتصال','IPAddresses'=>'IP (ورود دستی)','NetworkSharing'=>'اشتراک‌گذاری شبکه','Duplex'=>'چاپ دورو','Building'=>'ساختمان','Floor'=>'طبقه','Room'=>'اتاق'], 'display'=>['DisplayTechnology'=>'فناوری نمایشگر','DisplaySize'=>'اندازه نمایشگر','DisplayResolution'=>'رزولوشن نمایشگر','DisplaySerial'=>'سریال نمایشگر','Connection'=>'نوع اتصال'], 'scanner'=>['ScannerType'=>'نوع اسکنر','ScannerResolution'=>'رزولوشن اسکنر','ScannerConnection'=>'اتصال اسکنر','ScannerDuplex'=>'اسکن دورو','IPAddresses'=>'IP (ورود دستی)']];
function tv(string $k):string{global $technical,$arrayFields;$v=$technical[$k]??'';if(in_array($k,$arrayFields,true)){if(is_array($v))return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);$d=json_decode((string)$v,true);return is_array($d)?json_encode($d,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT):(string)$v;}return is_array($v)?json_encode($v,JSON_UNESCAPED_UNICODE):(string)$v;}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ویرایش <?=e($assetNo)?></title><link rel="stylesheet" href="assets/app.css"></head><body><header><a class="brand" href="index.php">سامانه سخت‌افزار</a><nav><a href="index.php">داشبورد</a><a href="assets.php?type=<?=e($asset['asset_type'])?>">پایگاه مربوطه</a><a href="asset_view.php?asset_no=<?=e($assetNo)?>">مشاهده</a><a href="logout.php">خروج</a></nav></header><main><div class="page-head"><div><h1>ویرایش تجهیز <?=e($assetNo)?></h1><p class="muted">فیلدهای آرایه‌ای با JSON قابل ویرایش هستند.</p></div></div><?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><form method="post" class="panel"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="asset_no" value="<?=e($assetNo)?>"><h2>مشخصات اصلی</h2><div class="form-grid"><label>شماره اموال<input value="<?=e($assetNo)?>" disabled></label><label>نوع دستگاه<select name="asset_type"><?php foreach(['computer'=>'پایگاه رایانه','printer'=>'چاپگر','display'=>'نمایشگر','scanner'=>'اسکنر'] as $k=>$v):?><option value="<?=$k?>" <?=$asset['asset_type']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>زیرنوع<input name="device_subtype" value="<?=e($asset['device_subtype'])?>"></label><label>نام دستگاه / Hostname<input name="hostname" value="<?=e($asset['hostname'])?>"></label><label>کاربر اصلی / مسئول<select name="personnel_id"><option value="">انتخاب پرسنل</option><?php foreach($people as $p):?><option value="<?=$p['id']?>" <?=$asset['personnel_id']==$p['id']?'selected':''?>><?=e($p['full_name'].' — '.($p['personnel_code']??''))?></option><?php endforeach;?></select></label><label>مکان<input name="location" value="<?=e($asset['location'])?>"></label><label>دانشکده / اداره / گروه<input name="department" value="<?=e($asset['department'])?>"></label><label>برند<input name="manufacturer" value="<?=e($asset['manufacturer'])?>"></label><label>مدل<input name="model" value="<?=e($asset['model'])?>"></label><label>شماره سریال<input name="serial_no" value="<?=e($asset['serial_no'])?>"></label><label>وضعیت<select name="status"><?php foreach(['active'=>'فعال','repair'=>'تعمیر','retired'=>'اسقاط','lost'=>'مفقود'] as $k=>$v):?><option value="<?=$k?>" <?=$asset['status']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label></div><h2>فیلدهای تخصصی <?=$technicalKeys[$asset['asset_type']]??[]?'': ' '?></h2><div class="form-grid"><?php foreach(($technicalKeys[$asset['asset_type']]??[]) as $k=>$label):?><label><?=e($label)?><textarea name="technical[<?=e($k)?>]" rows="3" <?=in_array($k,$arrayFields,true)?'dir="ltr"':''?>><?=e(tv($k))?></textarea></label><?php endforeach;?></div><?php if($asset['asset_type']==='computer'):?><h2>دیسک‌ها</h2><div class="table-wrap"><table><thead><tr><th>#</th><th>مدل</th><th>ظرفیت GB</th><th>سریال</th><th>رابط</th><th>رسانه</th></tr></thead><tbody><?php for($i=0;$i<max(6,count($disks));$i++):$d=$disks[$i]??[];?><tr><td><?=$i+1?></td><td><input name="disks[<?=$i?>][model]" value="<?=e($d['model']??'')?>"></td><td><input name="disks[<?=$i?>][size_gb]" value="<?=e($d['size_gb']??'')?>"></td><td><input name="disks[<?=$i?>][serial_no]" value="<?=e($d['serial_no']??'')?>"></td><td><input name="disks[<?=$i?>][interface_name]" value="<?=e($d['interface_name']??'')?>"></td><td><input name="disks[<?=$i?>][media]" value="<?=e($d['media']??'')?>"></td></tr><?php endfor;?></tbody></table></div><h2>اسلات‌های RAM</h2><div class="table-wrap"><table><thead><tr><th>اسلات</th><th>وضعیت</th><th>ظرفیت</th><th>نوع</th><th>فرکانس</th><th>برند</th><th>Part</th><th>Serial</th></tr></thead><tbody><?php for($i=0;$i<max(6,count($rams));$i++):$r=$rams[$i]??[];?><tr><td><input name="rams[<?=$i?>][slot_no]" value="<?=e($r['slot_no']??('DIMM_'.($i+1)))?>"></td><td><select name="rams[<?=$i?>][state]"><?php foreach(['occupied'=>'نصب‌شده','empty'=>'خالی','unknown'=>'نامشخص'] as $k=>$v):?><option value="<?=$k?>" <?=($r['state']??'unknown')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></td><td><input name="rams[<?=$i?>][capacity_gb]" value="<?=e($r['capacity_gb']??'')?>"></td><td><input name="rams[<?=$i?>][ram_type]" value="<?=e($r['ram_type']??'')?>"></td><td><input name="rams[<?=$i?>][speed_mhz]" value="<?=e($r['speed_mhz']??'')?>"></td><td><input name="rams[<?=$i?>][manufacturer]" value="<?=e($r['manufacturer']??'')?>"></td><td><input name="rams[<?=$i?>][part_number]" value="<?=e($r['part_number']??'')?>"></td><td><input name="rams[<?=$i?>][serial_no]" value="<?=e($r['serial_no']??'')?>"></td></tr><?php endfor;?></tbody></table></div><?php endif;?><div class="actions"><button class="btn primary">ذخیره تغییرات</button><a class="btn" href="asset_view.php?asset_no=<?=e($assetNo)?>">انصراف</a></div></form></main></body></html>
